/**
 * html2canvas lightweight fallback & canvas exporter utility for TokkoKit Pro
 * Provides window.html2canvas if CDN loading is unavailable offline.
 */
(function(window) {
  if (window.html2canvas) return;

  window.html2canvas = function(element, options) {
    options = options || {};
    return new Promise(function(resolve, reject) {
      try {
        const width = element.offsetWidth || 400;
        const height = element.offsetHeight || 600;

        const canvas = document.createElement('canvas');
        const scale = options.scale || 2; // High DPI export
        canvas.width = width * scale;
        canvas.height = height * scale;
        const ctx = canvas.getContext('2d');
        ctx.scale(scale, scale);

        // Draw styled background
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, width, height);

        // Render element clone into SVG foreignObject for crisp image export
        const clone = element.cloneNode(true);
        // Ensure white background and explicit styling on clone
        clone.style.backgroundColor = '#ffffff';
        clone.style.color = '#1e293b';
        clone.style.width = width + 'px';
        clone.style.height = height + 'px';
        clone.style.padding = '20px';
        clone.style.boxSizing = 'border-box';

        const wrapper = document.createElement('div');
        wrapper.appendChild(clone);

        const svgData = `
          <svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}">
            <foreignObject width="100%" height="100%">
              <div xmlns="http://www.w3.org/1999/xhtml" style="background:#ffffff; color:#1e293b; font-family: sans-serif;">
                ${wrapper.innerHTML}
              </div>
            </foreignObject>
          </svg>
        `;

        const img = new Image();
        const svgBlob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
        const url = URL.createObjectURL(svgBlob);

        img.onload = function() {
          ctx.drawImage(img, 0, 0);
          URL.revokeObjectURL(url);
          resolve(canvas);
        };

        img.onerror = function(err) {
          // Fallback simple draw
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(0, 0, width, height);
          ctx.fillStyle = '#1e293b';
          ctx.font = '16px sans-serif';
          ctx.fillText('TokkoKit Receipt Export', 20, 40);
          resolve(canvas);
        };

        img.src = url;
      } catch (err) {
        reject(err);
      }
    });
  };
})(window);
